import{j as e}from"./blog-pages-CKzVvxdf.js";import{I as t}from"./I18nErpPage-DL1_36Ls.js";import"./PillarHubNav-B5-hpTDP.js";import"./badge-rTcNiiok.js";const i={heroBadge:"حل تخطيط موارد المؤسسات للاختبارات غير المتلفة",heroTitle:"حل أتلانتيس المتكامل للاختبارات غير المتلفة",heroSubtitle:"منصة شاملة لإدارة شركات الفحص والتفتيش",heroIntro:"نظام تخطيط موارد متكامل مصمم خصيصًا لشركات الاختبارات غير المتلفة في الشرق الأوسط وشمال إفريقيا. أدوات إدارة المشاريع، وتتبع شهادات الفنيين، ومعايرة المعدات، والفوترة، والمخزون، وضوابط وثائق ISO 9001 في منصة واحدة.",ctaPrimary:"اطلب عرضًا توضيحيًا",ctaSecondary:"English version",statCompanies:"شركة فحص حول العالم",statRating:"متوسط تقييم العملاء",statAdminReduction:"تقليل الوقت الإداري",statModules:"وحدات رئيسية",marketContextLabel:"حل تخطيط موارد متخصص",painPointsTitle:"لماذا يحتاج قطاع الاختبارات غير المتلفة إلى نظام تخطيط موارد متخصص؟",painPointsSubtitle:"ثلاثة تحديات لا تستطيع برامج تخطيط الموارد العامة حلها",problemLabel:"المشكلة",solutionLabel:"الحل",modulesTitle:"ست وحدات أساسية لحل أتلانتيس المتكامل",modulesSubtitle:"كل وحدة مصممة خصيصًا لقطاع التفتيش الصناعي، وليست برنامج أعمال عامًا أعيد تسميته",roiTitle:"العائد على الاستثمار من حل أتلانتيس",faqTitle:"الأسئلة الشائعة — حل أتلانتيس المتكامل",alsoServingTitle:"خدمات أخرى",finalCtaTitle:"هل أنت مستعد لتحويل عمليات شركة الاختبارات غير المتلفة لديك؟",finalCtaBody:"انضم إلى أكثر من 127 شركة فحص حول العالم تستخدم حل أتلانتيس لإدارة الفحص والتفتيش. اطلب عرضًا توضيحيًا مخصصًا لاحتياجاتك.",finalCtaPrimary:"اطلب عرضًا توضيحيًا",finalCtaSecondary:"View English version",switchLangLabel:"English version"};function a(){return e.jsx(t,{lang:"ar",dir:"rtl",city:"الشرق الأوسط",countryCode:"AE",countryName:"الشرق الأوسط وشمال إفريقيا",slug:"ndt-erp-solution",canonicalPath:"/ar/ndt-erp-solution",englishPath:"/ndt-erp-solution",pageTitle:"حل أتلانتيس المتكامل للاختبارات غير المتلفة | نظام تخطيط موارد متخصص",pageDescription:"حل تخطيط موارد متكامل لشركات الاختبارات غير المتلفة. إدارة المشاريع، تتبع شهادات الفنيين، معايرة المعدات، الفوترة، المخزون، ضوابط وثائق ISO 9001.",keywords:"حل NDT متكامل, تخطيط موارد فحص, إدارة شركة تفتيش, ISO 9001, ASNT, API, تتبع شهادات, معايرة معدات",marketContext:"تواجه شركات الاختبارات غير المتلفة في الشرق الأوسط تحديات تشغيلية فريدة لا تستطيع برامج تخطيط الموارد العامة مثل SAP أو Oracle حلها دون تخصيص مكلف. تشمل هذه التحديات تتبع شهادات الفنيين متعددة المنهجيات (ASNT و ISO 9712 و PCN و CSWIP)، وإدارة معايرة معدات الفحص بمعايير ASTM E797 و ISO 17025، وإصدار تقارير بصيغ API محددة مع توقيعات وأختام رقمية، ومتابعة فترات الفحص القائم على المخاطر (RBI) وفق API RP 580. يقدم حل أتلانتيس المتكامل للاختبارات غير المتلفة منصة موحدة تجمع جميع هذه الوظائف، مع تكامل مدمج مع QuickBooks Online و SAP S/4HANA و Microsoft Dynamics 365 لإدارة المالية، وبرامج إدارة المشاريع، وبوابة العملاء والمقاولين من الباطن. تم تطوير الحل بمدخلات مباشرة من مجتمع الاختبارات غير المتلفة في حيدر آباد ودبي والرياض، ويخدم حاليًا أكثر من 127 شركة فحص حول العالم بتقييم متوسط 4.8 من 5.",roiBody:"يبلّغ عملاء حل أتلانتيس المتكامل عن تقليل الوقت الإداري بنسبة 40% خلال أول ستة أشهر من النشر، وتقليص دورة الفوترة من 45 يومًا إلى 18 يومًا في المتوسط، واختفاء حوادث انتهاء الشهادات بفضل التنبيهات الآلية. كما تقلل وحدة إدارة المشاريع وقت إعداد عروض الأسعار بنسبة 60٪، بينما تختصر وحدة المخزون المرتبطة بمعدات الفحص الوقت اللازم لتأكيد توفر المعدات لمشروع جديد من ساعات إلى دقائق. لشركة فحص متوسطة الحجم تضم 50 موظفًا، يمثل ذلك توفيرًا سنويًا يقدر بين 220,000 و310,000 دولار أمريكي، إضافة إلى تحسين الجاهزية للتدقيق وتقليل مخاطر فقدان عقود العملاء الرئيسيين.",painPoints:[{title:"برامج تخطيط الموارد العامة غير مناسبة",problem:"تتطلب SAP و Oracle و NetSuite تخصيصًا مكلفًا (200,000 - 500,000 دولار) لإضافة وظائف خاصة بقطاع الاختبارات غير المتلفة مثل تتبع شهادات ASNT أو قوالب تقارير API، مع نتائج غالبًا غير مرضية.",solution:"يصل حل أتلانتيس جاهزًا بكامل الوظائف المتخصصة في الاختبارات غير المتلفة من اليوم الأول دون أي تخصيص، بسعر سنوي يبدأ من 18,000 دولار لشركات الفحص الصغيرة."},{title:"جداول البيانات لا تتوسع",problem:"تعتمد العديد من شركات الفحص على جداول Excel لمتابعة الشهادات والمعدات والمشاريع، مما يؤدي إلى أخطاء بشرية وفقدان البيانات عند نمو الشركة وتوظيف المزيد من الفنيين.",solution:"منصة سحابية موحدة تتعامل مع آلاف السجلات في الوقت الفعلي، مع نسخ احتياطية تلقائية وصلاحيات وصول دقيقة لكل دور وظيفي."},{title:"غياب التكامل بين الأقسام",problem:"تستخدم العديد من شركات الفحص أنظمة منفصلة للمحاسبة (QuickBooks) وإدارة المشاريع (Asana) وتتبع الشهادات (Excel)، مما يخلق حواجز بيانات ويتطلب إدخالًا يدويًا متكررًا.",solution:"حل متكامل واحد يربط البيانات المالية ببيانات المشاريع وبيانات الفنيين في الوقت الفعلي، مع تكاملات مدمجة مع QuickBooks و SAP و Microsoft Dynamics."}],modules:[{title:"إدارة الفنيين والأفراد",description:"تتبع كل شهادة — ASNT SNT-TC-1A و ISO 9712 و PCN و CGSB و NAS 410 — مع مصفوفة الطرق وسجلات حدة البصر (Jaeger #2 / Snellen 20/30) وتواريخ إعادة الاختبار السنوية وخطابات صاحب العمل. تنبيهات آلية قبل 90 و60 و30 يومًا من الانتهاء.",features:["تتبع متعدد المنهجيات: UT, RT, MT, PT, VT, ET","سجلات حدة البصر السنوية","تواريخ إعادة الاختبار وخطابات صاحب العمل","تنبيهات تلقائية بالانتهاء","مصفوفة المؤهلات حسب العميل"]},{title:"تتبع معايرة المعدات",description:"فترات المعايرة وفق ASTM E797 و ASTM E1316 و ISO 17025. سجلات التتبع لـ NIST. دورة حياة الكتل والمحولات والأجهزة. تنبيهات تجاوز السماحية توقف النشر الميداني تلقائيًا.",features:["متتبع تواريخ المعايرة","تتبع NIST traceability","دورة حياة الكتل القياسية","تنبيهات تجاوز السماحية","أرشيف شهادات المعايرة بـ SHA-256"]},{title:"إدارة المشاريع وأوامر العمل",description:"العرض → التسعير → أمر الشراء → الجدولة → التنفيذ الميداني → التقرير → الفاتورة. مصفوفة RACI لكل مشروع. بوابة المقاولين من الباطن لأعمال عملاء العميل.",features:["تدفق العمل الكامل من العرض إلى الفاتورة","ربحية المشروع لكل مشروع","استخدام الفنيين لكل فني","مصفوفة RACI","بوابة المقاولين من الباطن"]},{title:"ضبط الإجراءات والوثائق",description:"الممارسة المكتوبة (WP) والإجراءات (وفق ASME القسم الخامس ISO 17635) والتعليمات والمبررات الفنية. متحكمة بالإصدارات مع تواريخ السريان والانتهاء وتوقيع المستوى الثالث المعتمد.",features:["ضبط إصدارات الإجراءات","توقيع المستوى الثالث المعتمد","توزيع آلي للأفراد المخولين","متوافق مع ISO 9001:2015 §7.5","مكتبة قوالب ASME BPVC"]},{title:"الإدارة المالية والفوترة",description:"متعدد العملات ومتعدد السلطات الضريبية. تكامل مدمج مع QuickBooks Online و Xero و SAP S/4HANA و Microsoft Dynamics 365 و Tally Prime و Zoho Books.",features:["متعدد العملات","تكامل QuickBooks/Xero/SAP","تكلفة البضائع المباعة لكل مشروع","الفوترة الآلية بالمعالم","متوافق مع GAAP/IFRS/VAT"]},{title:"بوابة العملاء والمقاولين من الباطن",description:"وصول العملاء الفوري إلى تقدم المشروع والتقارير المنجزة والفواتير. بوابة المقاولين من الباطن لتسليم الأعمال والتقارير.",features:["وصول العملاء على مدار الساعة","بوابة تسليم المقاولين من الباطن","إشعارات تلقائية للعملاء","أرشيف التقارير المنجزة","تتبع حالة الفواتير"]}],integrations:["QuickBooks Online و Xero و SAP S/4HANA","Microsoft Dynamics 365 و Tally Prime و Zoho Books","تكامل ASNT SNT-TC-1A لتتبع الشهادات","قوالب تقارير API 510 و API 570 و API 653","ASTM E797 و ISO 17025 لمعايرة المعدات","ISO 9001:2015 لضبط الوثائق","بوابات موردي أرامكو وأدنوك وقطر للطاقة","تكامل Maximo و SAP PM و IBM CMMS"],faqs:[{question:"ما الفرق بين حل أتلانتيس و SAP أو Oracle؟",answer:"تتطلب SAP و Oracle تخصيصًا مكلفًا (200,000 - 500,000 دولار) وفترات تنفيذ تصل إلى 18 شهرًا لإضافة وظائف خاصة بقطاع الاختبارات غير المتلفة. حل أتلانتيس يصل جاهزًا بكامل هذه الوظائف من اليوم الأول، بسعر سنوي يبدأ من 18,000 دولار وفترة تنفيذ من 4 إلى 6 أسابيع لشركة فحص نموذجية."},{question:"هل يدعم النظام شركات الفحص متعددة المواقع؟",answer:"نعم. تم تصميم الحل لشركات الفحص ذات المكاتب المتعددة في دول مختلفة، مع لوحة قيادة موحدة لرؤية كل العمليات، وفصل البيانات حسب الموقع، وعملات وضرائب متعددة، ودعم اللغات العربية والإنجليزية والإسبانية والفرنسية."},{question:"ما هي تكلفة الاشتراك السنوي؟",answer:"تبدأ الحزمة الأساسية من 18,000 دولار سنويًا لشركات الفحص الصغيرة (حتى 10 فنيين)، وتصل إلى 120,000 دولار سنويًا للشركات الكبرى متعددة المواقع (أكثر من 100 فني). تشمل جميع الحزم التحديثات والدعم الفني والاستضافة السحابية."},{question:"هل يمكن استيراد بياناتنا التاريخية من جداول البيانات؟",answer:"نعم. يوفر فريق التنفيذ قوالب استيراد Excel للأصول والمعدات وسجلات الموظفين والمشاريع التاريخية. يتولى متخصص تنفيذ مكرس التحقق من البيانات قبل النشر، وعادة ما يكتمل ترحيل البيانات والتشغيل في 4 إلى 6 أسابيع."},{question:"هل النظام آمن ومتوافق مع متطلبات سيادة البيانات في الخليج؟",answer:"نعم. النظام مستضاف على خوادم آمنة في مراكز بيانات معتمدة بمعايير ISO 27001. للعملاء الذين يتطلبون استضافة محلية في الخليج (للامتثال لمتطلبات سيادة البيانات في السعودية والإمارات وقطر)، نوفر خيار الاستضافة على مراكز بيانات إقليمية معتمدة في الرياض ودبي."}],ui:i})}export{a as default};
